 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    out = [[background for _ in range(w)] for _ in range(h)]
    seen = [[False] * w for _ in range(h)]

    # Keep dense colored objects, expand each object's bounding box to a solid
    # rectangle, and discard isolated noise marks.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            component = []
            while q:
                rr, cc = q.popleft()
                component.append((rr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if 0 <= nr < h and 0 <= nc < w and not seen[nr][nc] and grid[nr][nc] == color:
                        seen[nr][nc] = True
                        q.append((nr, nc))
            r0 = min(rr for rr, _ in component)
            r1 = max(rr for rr, _ in component)
            c0 = min(cc for _, cc in component)
            c1 = max(cc for _, cc in component)
            area = (r1 - r0 + 1) * (c1 - c0 + 1)
            if area >= 8 and len(component) / area >= 0.5:
                for rr in range(r0, r1 + 1):
                    for cc in range(c0, c1 + 1):
                        out[rr][cc] = color
    return out
